import java.util.*;

class Solution {
  public int minSpaceWastedKResizing(int[] nums, int k) {
    int n = nums.length, INF = Integer.MAX_VALUE / 4;
    int[][] dp = new int[k + 2][n + 1];
    for (int[] row : dp) Arrays.fill(row, INF);
    dp[0][0] = 0;
    for (int groups = 1; groups <= k + 1; groups++) {
      for (int end = groups; end <= n; end++) {
        int max = 0, sum = 0;
        for (int start = end; start >= groups; start--) {
          max = Math.max(max, nums[start - 1]);
          sum += nums[start - 1];
          dp[groups][end] =
              Math.min(dp[groups][end], dp[groups - 1][start - 1] + max * (end - start + 1) - sum);
        }
      }
    }
    return dp[k + 1][n];
  }
}
